import{_ as i}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as t}from"./chunks/CrystalBall.BdqnOTQQ.js";import{_ as a,a as o,b as r,c as s,d as n,e as l,f as p,g as d,h as c,i as m,j as u,k as h}from"./chunks/M-S-PS2c2.DvbnSuBF.js";import{_ as b}from"./chunks/M-S-PS5b.B4zocwby.js";import{_ as f,o as g,c as y,a3 as v}from"./chunks/framework.g9mfNVRQ.js";const z=JSON.parse('{"title":"Predictive Simulation","description":"","frontmatter":{},"headers":[],"relativePath":"use/predictions.md","filePath":"use/predictions.md"}'),w={name:"use/predictions.md"};function _(x,e,k,T,S,P){return g(),y("div",null,[...e[0]||(e[0]=[v('<div class="admonition xdrip"><p class="admonition-title"><img src="'+i+'" style="zoom:75%;"></p><p> Settings<br>  <img src="'+t+'" style="width:5%;"> Predictive Simulations</p></div><p>xDrip Predictive Simulation settings is an experimental, non medically approved feature. Make sure to re-read the <a href="./../install/install.html#understand-what-is-xdrip">EULA</a> before enabling it. Do not use them to make medical decisions.</p><div class="warning custom-block"><p class="custom-block-title">Warning</p><p>If you use a closed-loop system do not rely on these predictions since they don&#39;t take into account basal modulation.</p></div><div class="admonition xdripitem"><p class="admonition-title">Predictive simulations</p><p> Display mathematical simulations based on profile data and carbs/insulin logs</p></div><p>Enabling predictions will add the light purple prediction curve on the main graph. This curve is showing you how your BG should theoretically evolve using current insulin and carbs entered in xDrip. More details on display <a href="./display.html#treatments-and-predictions-curves">here</a>.</p><img src="'+a+'" style="zoom:75%;"><p>xDrip can handle multiple insulin types. See <a href="#multiple-insulin-types">below</a>.</p><div class="admonition xdripitem"><p class="admonition-title">Multiple Insulin Types</p><p> Options for working with multiple insulin types</p></div><h3 id="carb-ratio-and-insulin-sensitivity" tabindex="-1">Carb ratio and insulin sensitivity <a class="header-anchor" href="#carb-ratio-and-insulin-sensitivity" aria-label="Permalink to &quot;Carb ratio and insulin sensitivity&quot;">​</a></h3><div class="info custom-block"><p class="custom-block-title">Automatic import</p><p>If you use <a href="./interapp.html#receiving-from-nsclient">accepting treatments</a> from AAPS or NSClient, these parameters and the basal profile will automatically import at profile switch.</p></div><p>These parameters are key to diabetes management and should be known.<br> They will most probably vary during the day and should be calculated for every meal and also outside meal times.<br> Everybody has his own parameters. Don&#39;t use other people&#39;s parameters.</p><p>Carb ratio is the amount of carbohydrates that will be covered by 1 unit of insulin.</p><p>For example 10 means each 10g of carbohydrates will require 1 unit of insulin.</p><div class="admonition xdripitem"><p class="admonition-title">Carb Ratio</p><p> Grams of Carbohydrate 1 Unit covers</p></div><p>Insulin sensitivity is the resulting blood glucose drop for one unit of insulin, with no carbohydrates in the blood stream.</p><p>For example 50 (or 2.8) means 1 unit drops BG by 50 mg/dl (or 2.8 mmol/l).</p><div class="admonition xdripitem"><p class="admonition-title">Insulin Sensitivity</p><p> Glucose drop for 1 Unit</p></div><h3 id="carb-absorbtion-rate" tabindex="-1">Carb absorption rate <a class="header-anchor" href="#carb-absorbtion-rate" aria-label="Permalink to &quot;Carb absorption rate {#carb-absorbtion-rate}&quot;">​</a></h3><p>Carbohydrate absorption rate is the speed at which your body will assimilate carbohydrates. See <a href="https://diyps.org/2014/05/29/determining-your-carbohydrate-absorption-rate-diyps-lessons-learned/" target="_blank" rel="noreferrer">here</a> how to calculate that parameter.</p><div class="admonition xdripitem"><p class="admonition-title">Carb absorption rate</p><p> Linear model carbs absorbed per hour</p></div><p>Touching one of the two menus above will open the treatment profile editor.</p><img src="'+o+'" style="zoom:75%;"><p>You can define carbs per units of insulin and correction factor, just remember to validate the entry and not jump from one line to another without confirming an entry. Save when finished.</p><img src="'+r+'" style="zoom:75%;"><p>You will create blocks for different hours during the day.<br> To create (split) or delete a block, long touch the upper area of the block.</p><img src="'+s+'" style="zoom:75%;"><p>Touching the time bar at the top of a block allows you to change it; it will also propagate to the block below.<br> Eventually you&#39;ll end up having something like this.</p><img src="'+n+'" style="zoom:75%;"><p>If necessary you can perform a global percentage modification of all parameters with the slider at the bottom.<br> Remember to save.</p><img src="'+l+'" style="zoom:75%;"><h3 id="basal-profile-editor" tabindex="-1">Basal Profile Editor <a class="header-anchor" href="#basal-profile-editor" aria-label="Permalink to &quot;Basal Profile Editor&quot;">​</a></h3><div class="info custom-block"><p class="custom-block-title">This feature is under development.</p><p>Current basal profile is automatically imported from NSClient when <a href="./interapp.html#receiving-from-nsclient">Accept Treatments</a> is enabled.</p></div><div class="admonition xdripitem"><p class="admonition-title">Basal Profile Editor</p><p> Graphical editor for pump basal profiles</p></div><p>You can display and edit your basal profile.</p><ol><li>Select the profile you want to modify or view</li><li>Export (not functional yet)</li><li>Save locally</li></ol><img src="'+p+'" style="zoom:78%;"><p>To edit your basal profile:</p><ol><li>Touch the basal hour bar you want to modify, it will turn orange</li><li>Change the step if necessary</li><li>Use the positive numbered box or the upwards arrow to increase</li><li>Use the negative numbered box or the downwards arrow to decrease</li><li>Use set, or double tap the bar to set the new value</li></ol><img src="'+d+'" style="zoom:78%;"><h3 id="use-trend-momentum" tabindex="-1">Use trend momentum <a class="header-anchor" href="#use-trend-momentum" aria-label="Permalink to &quot;Use trend momentum&quot;">​</a></h3><p>Trend momentum is independent from predictions, it is just a mathematical extrapolation (i.e. if BG continues to evolve with its trend, not considering insulin and carbs, where will it go?) of your current BG trend (up/down/flat). It can be used for <a href="./alarms.html#forecasted-low-alert">Forecasted Low alarms</a>.</p><p>Trend momentum can be integrated in predictions (recommended).</p><div class="admonition xdripitem"><p class="admonition-title">Use trend momentum</p><p> Calculate including glucose trend</p></div><p>Including current trend (1) can prevent sharp prediction variations and might be closer to real evolution (2).</p><img src="'+c+'" style="zoom:75%;"><img src="'+b+'" style="zoom:75%;"><img src="'+m+'" style="zoom:75%;"><h3 id="eula" tabindex="-1">EULA <a class="header-anchor" href="#eula" aria-label="Permalink to &quot;EULA&quot;">​</a></h3><p>Review the <a href="./../install/install.html#understand-what-is-xdrip">EULA</a> before using this feature.</p><div class="admonition xdripitem"><p class="admonition-title">End User License Agreement</p><p> Not for medical use - research tool only</p></div><h3 id="low-level-prediction" tabindex="-1">Low Level prediction <a class="header-anchor" href="#low-level-prediction" aria-label="Permalink to &quot;Low Level prediction&quot;">​</a></h3><p>You can set up more prediction parameters here.</p><div class="admonition xdripitem"><p class="admonition-title">Low level prediction values</p><p> Deep settings for algorithms</p></div><p>Target is used for bolus wizard calculator. This is the desired BG target.</p><p>Insulin <a href="https://www.diabettech.com/insulin/why-we-are-regularly-wrong-in-the-duration-of-insulin-action-dia-times-we-use-and-why-it-matters/" target="_blank" rel="noreferrer">duration</a> depends on your insulin type. Changing the value requires xDrip restart (or phone restart).</p><p>Target Glucose Default is the value used to calculate suggested corrections.</p><div class="admonition xdripitem"><p class="admonition-title">Target Glucose Default</p><p> 100 / 5.6</p></div><p>Insulin duration is a parameter you should discuss with your endocrinologist. When using closed loop systems, this value will be much more. Still, remember that xDrip predictions find their best use with multiple daily injections, not with pumps.</p><div class="admonition xdripitem"><p class="admonition-title">Insulin duration in hours</p><p> 3</p></div><p>Liver parameters were introduced to take into account liver glycogen reaction to lows but are not characterizable easily and should be left at default values.</p><div class="admonition xdripitem"><p class="admonition-title">Default liver sensitivity ratio</p><p> 2</p></div><div class="admonition xdripitem"><p class="admonition-title">Default Liver Maximum Impact (0–1)</p><p> 0.8</p></div><h3 id="multiple-insulin-types" tabindex="-1">Multiple insulin types <a class="header-anchor" href="#multiple-insulin-types" aria-label="Permalink to &quot;Multiple insulin types&quot;">​</a></h3><div class="admonition xdripitem"><p class="admonition-title">Multiple insulin types</p></div><p>Select the insulin types you are using.</p><p>You can select up to three insulin types and then decide which one is used for basal and which for bolus.</p><div class="admonition xdripitem"><p class="admonition-title">Treatment profile editor</p><p>Enable at least one, max three profiles.<br>  ☐ FIASP (ultra-fast acting)<br>  ☐ Afrezza (ultra-fast acting)<br>  ☐ Apidra (ultra-fast acting)<br>  ☐ Novorapid (fast acting)<br>  ☐ Humalog (fast acting)<br>  ☐ Lispro (fast acting)<br>  ☐ Actrapid (short acting)<br>  ☐ Insulatard (NPH)<br>  ☐ Toujeo (long acting)<br>  ☐ Lantus (long acting)<br>  ☐ Levemir (long acting)<br>  ☐ Basaglar (long acting)<br>  ☐ Tresiba (ultra-long acting)</p></div><p>In the lower part of the dialog, select which insulin will be used for basal (long acting) and bolus (fast acting):</p><div class="admonition xdripitem"><p class="admonition-title">Choose basal insulin profile</p></div><div class="admonition xdripitem"><p class="admonition-title">Choose bolus insulin profile. Also used for pump and pen...</p></div><p>Once done, save your choices.</p><div class="admonition xdripitem"><p class="admonition-title"><span style="background-color:grey;color:white;">  CANCEL </span>  <span style="background-color:grey;color:white;">  RESET </span>       <span style="background-color:grey;color:white;">  SAVE </span>  </p></div><p>When adding multiple insulin types, using <a href="./mainUI.html#treatments">treatments</a> will ask you to select the one you&#39;re using for this treatment.</p><img src="'+u+'" style="zoom:75%;"><p>You can add basal insulin on the display and integrate it in calculation.<br> Not recommended as basal insulin in MDI is only used to keep background BG constant.<br> Use <a href="./mainUI.html#treatment-notes">notes</a> to track basal injections.</p><p>Multiple insulin types will be displayed in an identical way on the main graph.</p><div class="admonition xdripitem"><p class="admonition-title">Use Basal Activity</p><p> Plot basal activity on graph and incorporate in predictive model.</p></div><img src="'+h+'" style="zoom:75%;"><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Last modified 23/11/2026</em></a></p>',80)])])}const D=f(w,[["render",_]]);export{z as __pageData,D as default};
